// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        vm.assume(_feeRate <= 10000);
        address _baseToken = address(0);
        address _nft = address(0);
        uint128 _virtualBaseTokenReserves = 0;
        uint128 _virtualNftReserves = 0;
        uint56 _changeFee = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        bool success;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            success = true;
        } catch {
            success = false;
        }

        if (success) {
            assertTrue(c.feeRate() <= 5000);
        } else {
            assertTrue(_feeRate > 5000);
        }
    }
}
